package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	edges := make([][2]int, m)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(reader, &a, &b)
		edges[i] = [2]int{a - 1, b - 1}
	}

	labels := make([]int, n)
	best := 0

	var rec func(idx int)
	rec = func(idx int) {
		if idx == n {
			used := make(map[[2]int]bool)
			for _, e := range edges {
				a := labels[e[0]]
				b := labels[e[1]]
				if a > b {
					a, b = b, a
				}
				used[[2]int{a, b}] = true
			}
			if len(used) > best {
				best = len(used)
			}
			return
		}
		for v := 1; v <= 6; v++ {
			labels[idx] = v
			rec(idx + 1)
		}
	}
	rec(0)

	fmt.Println(best)
}
